def transform2(g):
    h,w=len(g),len(g[0])
    from collections import defaultdict
    res=None
    for mode in ('diag','row'):
        cls=defaultdict(set)
        for r in range(h):
            for c in range(w):
                if g[r][c]:
                    k=(c-r) if mode=='diag' else r
                    cls[k].add(g[r][c])
        for p in range(1,200):
            m={}; ok=True
            for off,cols in cls.items():
                k=off%p; col=next(iter(cols))
                if k in m and m[k]!=col: ok=False; break
                m[k]=col
            if ok and all(k in m for k in range(p)):
                out=[[m[((c-r) if mode=='diag' else r)%p] for c in range(w)] for r in range(h)]
                if res is None: res=out
                break
    return res
